-- Fix existing tables to allow manual ID inserts
-- Run this in Supabase SQL Editor

-- Drop existing sequences and recreate columns as GENERATED BY DEFAULT
ALTER TABLE drivers DROP CONSTRAINT IF EXISTS drivers_pkey CASCADE;
ALTER TABLE drivers ADD CONSTRAINT drivers_pkey PRIMARY KEY (id);
ALTER TABLE drivers ALTER COLUMN id DROP IDENTITY;
ALTER TABLE drivers ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE vehicles DROP CONSTRAINT IF EXISTS vehicles_pkey CASCADE;
ALTER TABLE vehicles ADD CONSTRAINT vehicles_pkey PRIMARY KEY (id);
ALTER TABLE vehicles ALTER COLUMN id DROP IDENTITY;
ALTER TABLE vehicles ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE quotations DROP CONSTRAINT IF EXISTS quotations_pkey CASCADE;
ALTER TABLE quotations ADD CONSTRAINT quotations_pkey PRIMARY KEY (id);
ALTER TABLE quotations ALTER COLUMN id DROP IDENTITY;
ALTER TABLE quotations ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE invoices DROP CONSTRAINT IF EXISTS invoices_pkey CASCADE;
ALTER TABLE invoices ADD CONSTRAINT invoices_pkey PRIMARY KEY (id);
ALTER TABLE invoices ALTER COLUMN id DROP IDENTITY;
ALTER TABLE invoices ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE payments DROP CONSTRAINT IF EXISTS payments_pkey CASCADE;
ALTER TABLE payments ADD CONSTRAINT payments_pkey PRIMARY KEY (id);
ALTER TABLE payments ALTER COLUMN id DROP IDENTITY;
ALTER TABLE payments ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE jobs DROP CONSTRAINT IF EXISTS jobs_pkey CASCADE;
ALTER TABLE jobs ADD CONSTRAINT jobs_pkey PRIMARY KEY (id);
ALTER TABLE jobs ALTER COLUMN id DROP IDENTITY;
ALTER TABLE jobs ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

SELECT 'All ID columns updated to allow manual inserts!' as status;
